// KNN-7 Direction Vote 3D
// KNN vote on next-bar direction: vote margin + neighbour disagreement

k = input(7, "K Neighbors", 1, 15, 1)
featureLookback = input(20, "Feature Lookback", 5, 40, 1)
searchLookback = input(200, "Search Lookback", 50, 500, 10)
marginThreshold = input(0.43, "Margin Threshold", 0.1, 1.0, 0.01)
crispDisagreementMax = input(0.35, "Crisp Disagreement Max", 0.05, 1.0, 0.01)
bullColor = input("#22cc88", "Bull Color")
bearColor = input("#ff4477", "Bear Color")
contestedColor = input("#888888", "Contested Color")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Persistent bar history ────────────────────────────────
varip openHist = array(0)
varip highHist = array(0)
varip lowHist = array(0)
varip closeHist = array(0)
varip dirHist = array(0)
varip rngHist = array(0)

dirNow = (close - open) / (open + 0.000000001)
rngNow = (high - low) / (open + 0.000000001)

array.push(openHist, open)
array.push(highHist, high)
array.push(lowHist, low)
array.push(closeHist, close)
array.push(dirHist, dirNow)
array.push(rngHist, rngNow)

// ─── KNN vote ──────────────────────────────────────────────
nBars = array.size(closeHist)

meanDir = 0.0
meanRng = 0.0
stdDir = 1.0
stdRng = 1.0
margin = 0.0
disagree = 1.0
crisp = 0.0
bullCount = 0
bearCount = 0

warmup = bar_index >= searchLookback + featureLookback

if warmup {
    // z-score baseline over searchLookback (manual mean / stdev, no MA template)
    sDir = 0.0
    sRng = 0.0
    c = 0
    while c < searchLookback {
        idx = nBars - 1 - c
        sDir := sDir + dirHist[idx]
        sRng := sRng + rngHist[idx]
        c := c + 1
    }
    meanDir := sDir / searchLookback
    meanRng := sRng / searchLookback
    vDir = 0.0
    vRng = 0.0
    c = 0
    while c < searchLookback {
        idx = nBars - 1 - c
        dD = dirHist[idx] - meanDir
        dR = rngHist[idx] - meanRng
        vDir := vDir + dD * dD
        vRng := vRng + dR * dR
        c := c + 1
    }
    stdDir := sqrt(vDir / searchLookback + 0.000000001)
    stdRng := sqrt(vRng / searchLookback + 0.000000001)

    // current feature vector (z-scored), kept in flat arrays
    curD = array()
    curR = array()
    f = 0
    while f < featureLookback {
        idx = nBars - 1 - f
        array.push(curD, (dirHist[idx] - meanDir) / (stdDir + 0.000000001))
        array.push(curR, (rngHist[idx] - meanRng) / (stdRng + 0.000000001))
        f := f + 1
    }

    // k smallest distances + their next-bar labels
    bestDist = array()
    bestLab = array()
    m = 0
    while m < k {
        array.push(bestDist, 999999999.0)
        array.push(bestLab, 0)
        m := m + 1
    }

    jStart = nBars - 1 - searchLookback
    if jStart < featureLookback { jStart := featureLookback }
    jEnd = nBars - 1

    j = jStart
    while j < jEnd {
        // Euclidean distance over 2*featureLookback dims
        ss = 0.0
        f = 0
        while f < featureLookback {
            idx = j - f
            zd = (dirHist[idx] - meanDir) / (stdDir + 0.000000001)
            zr = (rngHist[idx] - meanRng) / (stdRng + 0.000000001)
            dD = curD[f] - zd
            dR = curR[f] - zr
            ss := ss + dD * dD + dR * dR
            f := f + 1
        }
        dist = sqrt(ss + 0.000000001)
        // next-bar direction label of neighbour j
        lab = 0 - 1
        if closeHist[j + 1] > closeHist[j] { lab := 1 }

        // insertion sort into top-k
        insIdx = 0 - 1
        m = 0
        while m < k {
            if dist < bestDist[m] {
                insIdx := m
                m := k
            }
            m := m + 1
        }
        if insIdx >= 0 {
            m = k - 1
            while m > insIdx {
                array.set(bestDist, m, bestDist[m - 1])
                array.set(bestLab, m, bestLab[m - 1])
                m := m - 1
            }
            array.set(bestDist, insIdx, dist)
            array.set(bestLab, insIdx, lab)
        }
        j := j + 1
    }

    // Channel 1: vote margin
    bull = 0
    bear = 0
    m = 0
    while m < k {
        if bestDist[m] < 999999999.0 {
            if bestLab[m] == 1 { bull := bull + 1 }
            else { bear := bear + 1 }
        }
        m := m + 1
    }
    bullCount := bull
    bearCount := bear
    margin := (bull - bear) / (k + 0.000000001)

    // Channel 2: neighbour disagreement = stdev(D)/mean(D), distances only
    meanD = 0.0
    m = 0
    while m < k {
        meanD := meanD + bestDist[m]
        m := m + 1
    }
    meanD := meanD / k
    varD = 0.0
    m = 0
    while m < k {
        dd = bestDist[m] - meanD
        varD := varD + dd * dd
        m := m + 1
    }
    stdD = sqrt(varD / k + 0.000000001)
    disagree := stdD / (meanD + 0.000000001)
    crisp := abs(margin) * (1.0 - disagree)
}

// ─── Signal conditions: both channels must agree ───────────
prevMargin = margin[1]
prevDis = disagree[1]
bullArmed = margin > marginThreshold and disagree < crispDisagreementMax
bearArmed = margin < 0 - marginThreshold and disagree < crispDisagreementMax
prevBullArmed = prevMargin > marginThreshold and prevDis < crispDisagreementMax
prevBearArmed = prevMargin < 0 - marginThreshold and prevDis < crispDisagreementMax
buySig = warmup and bullArmed and not prevBullArmed
sellSig = warmup and bearArmed and not prevBearArmed

// ─── 2D signals (main chart) ───────────────────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    model.longEntry("KNNBuy")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    model.shortEntry("KNNSell")
}

// ─── 2D channels (separate pane, independently readable) ───
plot(margin, "Vote Margin", "#b48cff", 2, "separate")
plot(disagree, "Disagreement", "#ffaa00", 2, "separate")
plot(crisp, "Crispness", "#22cc88", 1, "separate")
hline(0, "#888888", "separate")

// ─── 3D form: bar-modulated channels so geometry varies every bar ──
// Channel 1: vote margin carried by price action (crisp = tall pillar)
barRange = high - low
marginDyn = close * (1.0 + margin * 0.05) + margin * barRange
// Channel 2: disagreement carried by a different price mix (contested = wide slab)
disagreeDyn = open * (1.0 + disagree * 0.05) + disagree * barRange
// Crispness shape factor: crisp -> stretched tall, contested -> flattened
shapeDyn = close * (1.0 + crisp * 0.05)

plot3d(marginDyn, "Margin Blocks", "bars3d", "#b48cff", "separate", 0)
plot3d(disagreeDyn, "Disagreement Cloud", "scatter", "#ffaa00", "separate", 1)

if buySig {
    plotshape_3d(bar_index, marginDyn, "Buy", "coneup", "#22cc88", markerSize, 0, "separate")
}
if sellSig {
    plotshape_3d(bar_index, marginDyn, "Sell", "conedown", "#ff4477", markerSize, 0, "separate")
}

// Visible Session Value Terrain Model
// Session volume profile: POC + value area expansion, breakout signals leaving value.

profileRows = input(24, "Profile Rows", 10, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(60, "Session Length Bars", 20, 200, 5)
show3D = input(true, "Show 3D Terrain")
show2D = input(true, "Show 2D Profile")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session range ───
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
rngFix = rng
if rngFix <= 0 { rngFix := close * 0.01 }
binH = rngFix / profileRows

// ─── Build volume-at-price bins from last sessLen bars ───
binVol = array()
i = 0
while i < profileRows {
    array.push(binVol, 0.0)
    i := i + 1
}
k = 0
while k < sessLen {
    c = close[k]
    v = volume[k]
    b = floor((c - ll) / rngFix * profileRows)
    if b < 0 { b := 0 }
    if b > profileRows - 1 { b := profileRows - 1 }
    array.set(binVol, b, array.get(binVol, b) + v)
    k := k + 1
}
totalVol = array.sum(binVol)

// ─── Point of control ───
pocBin = 0
pocVol = array.get(binVol, 0)
j = 1
while j < profileRows {
    vv = array.get(binVol, j)
    if vv > pocVol {
        pocVol := vv
        pocBin := j
    }
    j := j + 1
}
pocPrice = ll + (pocBin + 0.5) / profileRows * rngFix

// ─── Value area expansion from POC ───
vaLowBin = pocBin
vaHighBin = pocBin
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profileRows {
    leftV = 0 - 1.0
    if vaLowBin > 0 { leftV := array.get(binVol, vaLowBin - 1) }
    rightV = 0 - 1.0
    if vaHighBin < profileRows - 1 { rightV := array.get(binVol, vaHighBin + 1) }
    if rightV >= leftV and vaHighBin < profileRows - 1 {
        vaHighBin := vaHighBin + 1
        accum := accum + rightV
    } else {
        if vaLowBin > 0 {
            vaLowBin := vaLowBin - 1
            accum := accum + leftV
        }
    }
    guard := guard + 1
}
vahPrice = ll + (vaHighBin + 1) / profileRows * rngFix
valPrice = ll + vaLowBin / profileRows * rngFix
vaCenter = (vahPrice + valPrice) / 2
pocShare = 0.0
if totalVol > 0 { pocShare := pocVol / totalVol * 100 }

// ─── Signals: price leaving value ───
prevInside = close[1] >= valPrice and close[1] <= vahPrice
buySig = close > vahPrice and prevInside
sellSig = close < valPrice and prevInside

if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    model.longEntry("Buy")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    model.shortEntry("Sell")
}
if buySig and show3D { plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d") }
if sellSig and show3D { plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 2, "3d") }

// ─── POC rail label on new POC bin only ───
var wasPoc = -1
if pocBin != wasPoc and show3D { label3d(bar_index, pocPrice, "POC", "#ffd43b", 1.2, 1, "3d") }
wasPoc := pocBin

// ─── 2D: same POC/VAH/VAL levels when 3D is off ───
plot(pocPrice, "POC", "#ffd43b", 2, "stepline")
plot(vahPrice, "VAH", "#22cc88", 1, "stepline")
plot(valPrice, "VAL", "#ff4477", 1, "stepline")
plot(vaCenter, "Value Center", "#4488ff", 1)
plot(pocShare, "POC Share %", "#ffd43b", 1, "separate")

// ─── 3D: value terrain + POC labelled rail + VAH/VAL edge rails ───
plot3d(vaCenter, "Value Terrain", "surface", "#4488ff", "3d", 0)
plot3d(pocPrice, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahPrice, "VAH Rail", "line3d", "#22cc88", "3d", 2)

// Fix 1: var lvl = highest(high, 20) froze at bar 0 -> plain assignment recomputes every bar.
// Fix 2: close[-1] reads the future and leaks -> close > lvl uses current-bar breakout.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) is Pine -> OakScript plotshape(bar_index, price, title, style, color) with quoted style/color.
// Fix 4: RSI oscillator in pane="3d" renders spiky forest over price -> pane="separate" plus 2D twin plot.
lvl = highest(high, 20)
r = rsi(close, 14)
buySig = close > lvl
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if crossover(r, 30) {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(r, "RSI", "#b48cff", 1, "line")
plot3d(r, "RSI", "surface", "#b48cff", "separate")
